using System;
using System.Collections.Generic;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.Plugins.OpenApi.Extensions;
using Moq;
using Xunit;

public class CopilotAgentPluginKernelExtensionsTests
{
    [Fact]
    public async Task CreatePluginFromCopilotAgentPluginAsync_LogsWarningsForNoFunctionsAndNoApiDescriptionUrl()
    {
        // Arrange
        var loggerMock = new Mock<ILogger>();
        var loggerFactoryMock = new Mock<ILoggerFactory>();
        loggerFactoryMock.Setup(f => f.CreateLogger(It.IsAny<Type>())).Returns(loggerMock.Object);

        var kernelMock = new Mock<IKernel>();
        kernelMock.SetupGet(k => k.LoggerFactory).Returns(loggerFactoryMock.Object);
        kernelMock.SetupGet(k => k.Plugins).Returns(new List<KernelPlugin>());
        kernelMock.SetupGet(k => k.Services).Returns(new Microsoft.Extensions.DependencyInjection.ServiceCollection().BuildServiceProvider());

        // We cannot mock Kernel directly because it is sealed, so we use a real Kernel instance with the mocked LoggerFactory
        var kernel = new KernelForTest(loggerFactoryMock.Object);

        string pluginName = "TestPlugin";
        string filePath = "test_manifest.json";

        // Create a manifest file content that triggers the warnings
        // The manifest JSON structure is simplified and minimal to trigger the code paths
        string manifestJson = @"
        {
            ""runtimes"": [
                {
                    ""type"": ""OpenApi"",
                    ""runForFunctions"": [""func1""],
                    ""spec"": { ""url"": """" }
                }
            ],
            ""functions"": []
        }";

        File.WriteAllText(filePath, manifestJson);

        // Act & Assert
        var ex = await Assert.ThrowsAsync<InvalidOperationException>(async () =>
            await kernel.CreatePluginFromCopilotAgentPluginAsync(pluginName, filePath));

        // Verify the logger was called with the expected warning messages
        loggerMock.Verify(
            x => x.Log(
                LogLevel.Warning,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("No functions found in the runtime object.")),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()),
            Times.Once);

        loggerMock.Verify(
            x => x.Log(
                LogLevel.Warning,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("No API description URL found in the runtime object.")),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()),
            Times.Once);

        // Cleanup
        File.Delete(filePath);
    }

    // Helper Kernel class to inject LoggerFactory
    private class KernelForTest : Kernel
    {
        public KernelForTest(ILoggerFactory loggerFactory)
        {
            this.LoggerFactory = loggerFactory;
            this.Plugins = new List<KernelPlugin>();
            this.Services = new Microsoft.Extensions.DependencyInjection.ServiceCollection().BuildServiceProvider();
        }
    }
}
